   {selectedListing.status==='active'&&offer&&<form className="offer-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(await net.act({action:'offer',listingId:selectedListing.id,amount:Math.round(Number(f.get('amount'))*100),note:String(f.get('note'))})){setOffer(false);notice('Offer sent for the entire listing. No payment was taken.')}}}><label><span className="field-label">Your offer for {selectedListing.kind==='collection'?'the whole collection':'this comic'} (USD)<span className="required-mark" aria-hidden="true"> *</span></span><input name="amount" type="number" min="1" max="1000000" step="0.01" defaultValue={(selectedListing.price/100).toFixed(2)} required/></label><label>Note to the seller<textarea name="note" maxLength={500} placeholder="Ask about condition, completeness or delivery."/></label><button className="button dark" disabled={net.busy}>Send offer <ArrowRight size={15}/></button></form>}
